package auth

import (
	"net/http/httptest"
	"strconv"
	"strings"
	"testing"
	"time"
)

// Generated by PHP 8 password_hash("secret-password", PASSWORD_BCRYPT, ["cost" => 12])
// inside the legacy Laravel image.
const phpHash = "$2y$12$Q6OBfh6GVdSDD4/fTOxCxONvR5i/QSmVsZle4GUnBqpmuCfgjpABe"

func TestCheckPasswordLegacyPHPHash(t *testing.T) {
	if !CheckPassword(phpHash, "secret-password") {
		t.Fatal("legacy $2y$ hash should verify")
	}
	if CheckPassword(phpHash, "wrong") {
		t.Fatal("wrong password accepted")
	}
}

func TestHashPasswordRoundTrip(t *testing.T) {
	h, err := HashPassword("p@ssw0rd")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.HasPrefix(h, "$2a$12$") {
		t.Fatalf("unexpected hash format %q", h)
	}
	if !CheckPassword(h, "p@ssw0rd") || CheckPassword(h, "p@ssw0rD") {
		t.Fatal("round trip failed")
	}
	if CheckPassword("", "") || CheckPassword("not-a-hash", "x") {
		t.Fatal("empty/invalid hash must not match")
	}
	long := strings.Repeat("a", 100)
	hl, err := HashPassword(long)
	if err != nil {
		t.Fatalf("long password: %v", err)
	}
	// PHP semantics: only the first 72 bytes count.
	if !CheckPassword(hl, long) || !CheckPassword(hl, strings.Repeat("a", 72)) {
		t.Fatal("72-byte truncation mismatch")
	}
}

func TestGenerateAndHashToken(t *testing.T) {
	a, err := GenerateToken()
	if err != nil {
		t.Fatal(err)
	}
	b, _ := GenerateToken()
	if a == b || len(a) != 43 {
		t.Fatalf("tokens %q %q", a, b)
	}
	if len(HashToken(a)) != 32 || string(HashToken(a)) != string(HashToken(a)) {
		t.Fatal("hash must be 32 deterministic bytes")
	}
}

func TestBearerToken(t *testing.T) {
	cases := map[string]string{
		"Bearer abc":     "abc",
		"bearer  abc ":   "abc",
		"Basic abc":      "",
		"":               "",
		"Bearer":         "",
		"BEARER 1|token": "1|token",
	}
	for h, want := range cases {
		r := httptest.NewRequest("GET", "/", nil)
		if h != "" {
			r.Header.Set("Authorization", h)
		}
		if got := BearerToken(r); got != want {
			t.Errorf("%q: got %q want %q", h, got, want)
		}
	}
}

func TestNeedsTouch(t *testing.T) {
	now := time.Now()
	recent := now.Add(-time.Minute)
	old := now.Add(-10 * time.Minute)
	if !needsTouch(nil, now, 5*time.Minute) || needsTouch(&recent, now, 5*time.Minute) || !needsTouch(&old, now, 5*time.Minute) {
		t.Fatal("needsTouch")
	}
}

func TestPrimaryRole(t *testing.T) {
	cases := []struct {
		in   []string
		want string
	}{
		{nil, ""},
		{[]string{"student"}, "student"},
		{[]string{"student", "instructor"}, "instructor"},
		{[]string{"instructor", "advisor"}, "advisor"},
		{[]string{"advisor", "finance"}, "finance"},
		{[]string{"finance", "academic_manager", "student"}, "academic_manager"},
		{[]string{"student", "admin", "academic_manager"}, "admin"},
		{[]string{"custom", "student"}, "student"},
		{[]string{"custom", "other"}, "custom"},
	}
	for _, c := range cases {
		if got := PrimaryRole(c.in); got != c.want {
			t.Errorf("PrimaryRole(%v) = %q, want %q", c.in, got, c.want)
		}
	}
}

func TestVerificationSignature(t *testing.T) {
	now := time.Unix(1_700_000_000, 0)
	clock := func() time.Time { return now }
	s := NewSigner([]byte("0123456789abcdef0123456789abcdef"), clock)
	l := s.SignVerification(42, "a@b.vn", time.Hour)
	if l.Hash != EmailHash("a@b.vn") {
		t.Fatal("hash")
	}
	exp := strconv.FormatInt(l.Expires, 10)
	if !s.ValidVerification("42", l.Hash, exp, l.Signature) {
		t.Fatal("valid link rejected")
	}
	if !s.ValidVerification("42", l.Hash, exp, strings.ToUpper(l.Signature)) {
		t.Fatal("hex case should not matter")
	}
	for name, args := range map[string][4]string{
		"other id":      {"43", l.Hash, exp, l.Signature},
		"other hash":    {"42", EmailHash("x@b.vn"), exp, l.Signature},
		"other expires": {"42", l.Hash, strconv.FormatInt(l.Expires+1, 10), l.Signature},
		"no signature":  {"42", l.Hash, exp, ""},
		"no expires":    {"42", l.Hash, "", l.Signature},
		"bad expires":   {"42", l.Hash, "abc", l.Signature},
	} {
		if s.ValidVerification(args[0], args[1], args[2], args[3]) {
			t.Errorf("%s: accepted", name)
		}
	}
	other := NewSigner([]byte("ffffffffffffffffffffffffffffffff"), clock)
	if other.ValidVerification("42", l.Hash, exp, l.Signature) {
		t.Fatal("different key accepted")
	}
	now = now.Add(time.Hour + time.Second)
	if s.ValidVerification("42", l.Hash, exp, l.Signature) {
		t.Fatal("expired link accepted")
	}
}

func TestEmailHashIsSHA1(t *testing.T) {
	// sha1("test@example.com")
	if got := EmailHash("test@example.com"); got != "567159d622ffbb50b11b0efd307be358624a26ee" {
		t.Fatalf("got %s", got)
	}
}
